<?php
// Only synthetic databases are created, modified, and removed by this test.
if (PHP_SAPI !== 'cli') { http_response_code(404); exit; }
$keep=in_array('--keep',$argv,true);
$database='seniorlink_test_'.bin2hex(random_bytes(6));
$argv=[__FILE__,'setup',$database];
require_once dirname(__DIR__).'/includes/senior_classification.php';
require_once dirname(__DIR__).'/includes/classification_export.php';
$passed=0;
$check=static function(bool $ok,string $label)use(&$passed):void{if(!$ok)throw new RuntimeException($label);$passed++;echo "PASS {$label}\n";};
$reject=static function(callable $action,string $label)use($check):void{try{$action();}catch(Throwable $e){$check(true,$label);return;}throw new RuntimeException('Expected rejection: '.$label);};
try {
    require __DIR__.'/workflow_fixture.php';
    $migration=file_get_contents(dirname(__DIR__).'/database/migrations/20261027_senior_classifications.sql');
    $conn->exec($migration);$conn->exec($migration);
    $conn->exec("UPDATE applications SET is_archived=1");
    $conn->exec("UPDATE applications SET is_archived=0 WHERE id_number IN ('VALID','PRX-BENE','OTHER','DECEASED-LINK','CHANGE-REQUEST','VISIT')");
    $conn->exec("UPDATE applications SET workflow_state='Deceased',status='deceased',deceased_at=NOW() WHERE id_number='DECEASED-LINK'");
    $conn->exec("UPDATE applications SET workflow_state='Verified' WHERE id_number='CHANGE-REQUEST'");
    $conn->exec("UPDATE applications SET parent_senior_id='PRX-BENE' WHERE id_number='VISIT'");
    $conn->exec("UPDATE applications SET full_name='Same Name' WHERE id_number IN ('VALID','OTHER')");
    $id=(int)$conn->query("SELECT id FROM users WHERE username='test-admin'")->fetchColumn();
    $admin=classificationActor(['user_id'=>$id,'username'=>'test-admin','role'=>'department_admin']);
    $staff=classificationActor(['user_id'=>$id,'username'=>'test-staff','role'=>'barangay_staff','barangay'=>'Bagong Ilog']);
    $all=classificationFilters([],$admin);$scoped=classificationFilters(['barangay'=>'Ugong'],$staff);
    $summary=classificationSummary($conn,$all);
    $check($summary===['total'=>4,'active'=>3,'inactive'=>0,'unclassified'=>0,'residence_unclassified'=>0,'deceased'=>1],'Four primary profiles counted once; requests excluded and verified profiles automatically Active');
    $check(classificationSummary($conn,classificationFilters(['residence'=>'Within Pasig'],$admin))['total']===4,'Existing seniors automatically default to Within Pasig');
    $check(classificationProfile($conn,'OTHER',$admin)['residence_status']==='Within Pasig','New classification form receives automatic residence');
    $check(classificationSummary($conn,$scoped)['total']===3,'Barangay scope overrides tampered filter');
    $check(classificationProfile($conn,'OTHER',$staff)===null,'Other barangay detail denied');
    $check(classificationProfile($conn,'CHANGE-REQUEST',$admin)===null,'Linked ID change cannot be classified as a new senior');
    $check(classificationSummary($conn,classificationFilters(['search'=>'Same Name'],$admin))['total']===2,'Equal names do not merge separate people');
    $check(classificationSummary($conn,classificationFilters(['search'=>'%'],$admin))['total']===0,'Search wildcard is literal');
    $reject(fn()=>classificationActor([]),'Anonymous access rejected');
    $reject(fn()=>classificationActor(['user_id'=>1,'role'=>'barangay_staff']),'Unassigned staff rejected');
    $reject(fn()=>classificationFilters(['activity'=>'Invalid'],$admin),'Invalid filters rejected');
    $change=['profile_id'=>'VALID','activity_status'=>'Active','residence_status'=>'Within Pasig','effective_date'=>date('Y-m-d'),'reason'=>'Reviewed senior profile with current residence.','version'=>0];
    $reject(fn()=>saveSeniorClassification($conn,$staff,$change),'Staff cannot update classification');
    $reject(fn()=>saveSeniorClassification($conn,$admin,array_merge($change,['activity_status'=>'Unclassified'])),'Unclassified activity cannot be saved');
    $reject(fn()=>saveSeniorClassification($conn,$admin,array_merge($change,['effective_date'=>'2026-02-30'])),'Invalid calendar date rejected');
    $reject(fn()=>saveSeniorClassification($conn,$admin,array_merge($change,['effective_date'=>'2099-01-01'])),'Future date rejected');
    $reject(fn()=>saveSeniorClassification($conn,$admin,array_merge($change,['reason'=>''])),'Reason required');
    saveSeniorClassification($conn,$admin,$change);
    $saved=classificationProfile($conn,'VALID',$admin);
    $check($saved['activity_status']==='Active' && $saved['residence_status']==='Within Pasig' && (int)$saved['version']===1,'Classification saved with version');
    $reject(fn()=>saveSeniorClassification($conn,$admin,$change),'Stale update rejected');
    $reject(fn()=>saveSeniorClassification($conn,$admin,array_merge($change,['profile_id'=>'DECEASED-LINK'])),'Deceased cannot be overwritten');
    $check((int)$conn->query("SELECT COUNT(*) FROM senior_classification_history WHERE profile_id='VALID'")->fetchColumn()===1,'Rejected changes do not add history');
    $longReason='=SUM(1,1) Reviewed by José. '.str_repeat('Supporting review details. ',30).'END-OF-REASON';
    saveSeniorClassification($conn,$admin,array_merge($change,['activity_status'=>'Inactive','residence_status'=>'Outside Pasig','reason'=>$longReason,'version'=>1]));
    $saved=classificationProfile($conn,'VALID',$admin);
    $check((int)$saved['version']===2 && $saved['activity_status']==='Inactive','Updated classification persists');
    $check((int)$conn->query("SELECT COUNT(*) FROM senior_classification_history WHERE profile_id='VALID'")->fetchColumn()===2,'History records previous and new values');
    $check((int)$conn->query("SELECT COUNT(*) FROM audit_trail WHERE action='UPDATE_SENIOR_CLASSIFICATION'")->fetchColumn()===2,'Both changes appear in audit trail');
    $check(classificationSummary($conn,classificationFilters(['activity'=>'Inactive','residence'=>'Outside Pasig'],$admin))['total']===1,'Combined filters match saved classification');
    $sum=classificationSummary($conn,$all);$rows=classificationRows($conn,$all,5000);
    $check($sum['total']===count($rows) && array_sum(array_intersect_key($sum,array_flip(['active','inactive','unclassified','deceased'])))===$sum['total'],'Summary reconciles to rows and category totals');
    $check(count(classificationRows($conn,$all,2,2))===2,'Pagination retrieves the next unique profiles');
    $out=dirname(__DIR__).'/tmp/classification-qa';if(!is_dir($out))mkdir($out,0750,true);
    file_put_contents($out.'/classification.pdf',classificationPdf($rows,$all,$sum,$conn));
    file_put_contents($out.'/classification.xlsx',classificationExcel($rows,$all,$sum,$conn));
    file_put_contents($out.'/empty.pdf',classificationPdf([], $all, array_fill_keys(array_keys($sum),0)));
    file_put_contents($out.'/empty.xlsx',classificationExcel([], $all, array_fill_keys(array_keys($sum),0)));
    $check(str_starts_with(file_get_contents($out.'/classification.pdf'),'%PDF-1.4'),'PDF generated');
    $pdfBytes=file_get_contents($out.'/classification.pdf');
    $check(substr_count($pdfBytes,'/Subtype /Image')===2&&str_contains($pdfBytes,'REPUBLIC OF THE PHILIPPINES'),'PDF contains both logos and standard government header');
    $check(str_contains($pdfBytes,'Registered seniors:')&&str_contains($pdfBytes,'END-OF-REASON'),'PDF includes renamed total and complete long review note');
    $zip=new ZipArchive();$check($zip->open($out.'/classification.xlsx')===true,'Excel is a valid ZIP package');
    $sheet=$zip->getFromName('xl/worksheets/sheet1.xml');
    $check($zip->locateName('xl/media/Logo.png')!==false&&$zip->locateName('xl/media/OSCA.png')!==false,'Excel embeds both report logos');
    $check(str_contains($sheet,'REPUBLIC OF THE PHILIPPINES')&&str_contains($sheet,'CITY GOVERNMENT OF PASIG')&&str_contains($sheet,'Registered seniors:'),'Excel includes government header and registered senior total');
    $check(str_contains($zip->getFromName('xl/workbook.xml'),'_xlnm.Print_Titles'),'Excel repeats the report header on printed pages');
    $zip->close();
    $check(str_contains($sheet,'=SUM(1,1)') && !str_contains($sheet,'<f>'),'Reason exported as text, never an Excel formula');
    echo "{$passed} classification checks passed.\n";
    if($keep)echo json_encode(['database'=>$database,'admin_id'=>$id])."\n";
} finally {
    if(!$keep && isset($conn) && preg_match('/^seniorlink_test_[a-f0-9]{12}$/D',$database)) $conn->exec("DROP DATABASE IF EXISTS `{$database}`");
}
